-- 26 system role templates. tenant_id IS NULL marks a template that every
-- tenant may use. A school can copy one into its own editable role; it cannot alter
-- the template itself.
INSERT INTO identity.role (id, tenant_id, code, name, description, scope, is_system, is_assignable) VALUES
    (gen_random_uuid(), NULL, 'PLATFORM_SUPER_ADMIN', 'Platform Super Admin', 'Operates the platform itself. Deliberately holds no permission over a school’s student, health, discipline or academic records; entering a tenant requires a time-boxed, reasoned support grant.', 'PLATFORM', true, true),
    (gen_random_uuid(), NULL, 'PLATFORM_SUPPORT', 'Platform Support', 'Reads platform health and may request, never self-approve, tenant access.', 'PLATFORM', true, true),
    (gen_random_uuid(), NULL, 'SCHOOL_OWNER', 'School Owner', 'Full authority within one school, including subscription and role administration.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'SCHOOL_ADMIN', 'School Administrator', 'Day-to-day administration of people, structure and settings. Not finance approval, not payroll approval.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'HEADMASTER', 'Headmaster / Principal', 'Executive oversight. Reads widely and approves results; does not post journals or run payroll.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'ACADEMIC_HEAD', 'Academic Head', 'Owns the academic programme and the results pipeline up to approval.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'REGISTRAR', 'Registrar', 'Custodian of the student record and its documents.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'ADMISSIONS_OFFICER', 'Admissions Officer', 'Runs the admissions funnel. Cannot decide an offer alone.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'TEACHER', 'Teacher', 'Teaches assigned classes. Enters and submits marks, and deliberately cannot approve or publish the results they entered.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'CLASS_TEACHER', 'Class Teacher', 'A teacher with pastoral responsibility for one class: adds remarks and sees that class in full.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'HEAD_OF_DEPARTMENT', 'Head of Department', 'Reviews marks submitted by the department before they reach the academic head.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'BURSAR', 'Bursar', 'Owns fee collection and cash. Records payments and issues receipts; refund approval and journal posting sit with a different holder (maker-checker, spec 134).', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'ACCOUNTANT', 'Accountant', 'Prepares journals and reports. Cannot approve or post their own journal.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'FINANCE_MANAGER', 'Finance Manager', 'The checker in maker-checker: approves and posts journals, approves refunds, closes periods.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'HR_MANAGER', 'HR Manager', 'Owns the staff lifecycle. Sees salary data; does not approve payroll.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'PAYROLL_OFFICER', 'Payroll Officer', 'Prepares payroll. Approval and posting are deliberately absent (spec 158).', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'LIBRARIAN', 'Librarian', 'Runs the library catalogue and circulation.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'NURSE', 'Nurse / Health Officer', 'The only ordinary school role holding health records. Access is audited.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'COUNSELLOR', 'Counsellor', 'Confidential case work. Counselling notes are not visible to teachers or administrators.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'TRANSPORT_MANAGER', 'Transport Manager', 'Routes and vehicles. Pupil address data is restricted to what routing requires.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'HOSTEL_MANAGER', 'Hostel Manager', 'Boarding allocation and pastoral care in the hostel.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'STOREKEEPER', 'Storekeeper', 'Stock movements. Adjustments require the separate adjust permission.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'PROCUREMENT_OFFICER', 'Procurement Officer', 'Raises requisitions and orders. Approval sits with a different holder.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'ICT_ADMINISTRATOR', 'ICT Administrator', 'Technical administration. Deliberately excludes finance, payroll and health records: administering the system is not a reason to read a child’s medical notes.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'STUDENT', 'Student', 'Sees their own record only. Row-level filtering to the student is applied on top of these permissions.', 'SCHOOL', true, true),
    (gen_random_uuid(), NULL, 'GUARDIAN', 'Parent / Guardian', 'Sees linked wards only. Row-level filtering to the guardian link is applied on top of these permissions.', 'SCHOOL', true, true)
ON CONFLICT DO NOTHING;

-- Platform Super Admin: 7 permissions
INSERT INTO identity.role_permission (role_id, permission_id)
SELECT r.id, p.id
  FROM identity.role r
  JOIN identity.permission p ON p.code IN (
        'PLATFORM_AUDIT_VIEW',
        'PLATFORM_HEALTH_VIEW',
        'PLATFORM_SUBSCRIPTION_MANAGE',
        'PLATFORM_SUPPORT_APPROVE_ACCESS',
        'PLATFORM_TENANT_PROVISION',
        'PLATFORM_TENANT_SUSPEND',
        'PLATFORM_TENANT_VIEW'
       )
 WHERE r.code = 'PLATFORM_SUPER_ADMIN' AND r.tenant_id IS NULL
ON CONFLICT DO NOTHING;

